-- 003 — "where did this synthetic record come from?" (UNIVAULT_SPEC.md section 16.1, principle 6)
--
-- Plain English: every generated document carries a small label saying which program, version,
-- random seed, recipe and dataset produced it, so the vault can show "Synthetic: generated by
-- <recipe>, seed N". Real uploads leave it empty, so the column is optional (nullable).
-- This is a LABEL only: no decision in the app may look at it.
alter table public.documents add column if not exists synthetic_origin jsonb;

-- Recipients are invented organisations too; mark them synthetic like every other demo record.
alter table public.recipients add column if not exists synthetic boolean not null default true;
